function percentChange(from, to){
  from=Number(from); to=Number(to);
  if(!isFinite(from) || !isFinite(to)) return {ok:false, reason:'请输入有效数字'};
  if(from===0) return {ok:false, reason:'基准值不能为 0'};
  var d=to-from;
  return {ok:true, change:d, percent:d/Math.abs(from)*100, direction: d>0?'up':(d<0?'down':'flat')};
}
function partOf(part, whole){
  part=Number(part); whole=Number(whole);
  if(!isFinite(part) || !isFinite(whole)) return {ok:false, reason:'请输入有效数字'};
  if(whole===0) return {ok:false, reason:'总量不能为 0'};
  return {ok:true, percent:part/whole*100};
}

var EXPORTS={percentChange:percentChange,partOf:partOf};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PercentChangeForgePure = EXPORTS; }
